const response = $json;
const context = $('Prepare Article Generation Request').first().json;

if (response.error) {
  throw new Error('OpenAI article generation failed: ' + JSON.stringify(response.error));
}
if (response.status && response.status !== 'completed') {
  throw new Error('OpenAI response did not complete. Status: ' + response.status);
}

const message = (response.output || []).find((item) => item.type === 'message');
const outputText = message?.content?.find((item) => item.type === 'output_text')?.text;
if (!outputText) {
  throw new Error('OpenAI response did not contain structured output text.');
}

let publicationPackage;
try {
  publicationPackage = JSON.parse(outputText);
} catch (error) {
  throw new Error('Article package was not valid JSON: ' + error.message);
}

const html = publicationPackage.article_html || '';
const review = publicationPackage.review_document_markdown || '';
if (!html.trim()) {
  if (/HOLD|incomplete source interview|does not contain substantive/i.test(review)) {
    throw new Error('Interview does not contain enough substantive expert material to create an article. Complete a new interview before generating the draft.');
  }
  throw new Error('Production HTML is empty.');
}
if (!html.startsWith('<!-- SEO_TITLE:') || !html.includes('<h1>')) {
  throw new Error('Production HTML is missing required metadata comments or H1.');
}
if (/<(?:html|head|body|script|style)(?:\s|>)/i.test(html)) {
  throw new Error('Production HTML contains a forbidden document wrapper or executable/style tag.');
}
if (/<!--\s*(?:FACT CHECK|INTERVIEW BASIS|REVIEW NOTE|SOURCE|CLINICAL REVIEW|RESEARCH ADDITION)/i.test(html)) {
  throw new Error('Production HTML contains internal review comments.');
}
if (review.length < 1000) {
  throw new Error('Review document is unexpectedly short.');
}

const packageForStorage = {
  article_html: html,
  review_document_markdown: review,
  metadata: publicationPackage.metadata,
  openai_response_id: response.id,
  generated_at: new Date().toISOString()
};

return [{
  json: {
    interview_id: context.interview_id,
    campaign_id: context.campaign_id,
    doctor_id: context.doctor_id,
    practice_id: context.practice_id,
    topic_id: context.topic_id,
    article_id: context.article_id,
    doctor_review_days: Number(context.doctor_review_days || 5),
    article_html: html,
    review_document_markdown: review,
    metadata: publicationPackage.metadata,
    package_json: JSON.stringify(packageForStorage),
    openai_response_id: response.id
  }
}];
